288	func adapterReasoningPolicy(policy reasoning.Policy, fallback string) string {
289		switch policy.Kind {
290		case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
291			return ""
292		case reasoning.KindTokens:
293			if policy.Tokens == 0 {
294				return ""
295			}
296			return string(policy.Value)
297		case reasoning.KindNamed:
298			return string(policy.Value)
299		default:
300			return fallback
301		}
302	}
